<?php require_once 'functions.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){ $id=(int)($_POST['id']??0);$act=$_POST['action']??'';$amount=max(0,(int)($_POST['amount']??0));if($act==='delete'){db()->prepare('DELETE FROM stocks WHERE id=?')->execute([$id]);flash('Stock deleted.');}elseif(in_array($act,['add','remove'],true)&&$amount>0){$q=db()->prepare('SELECT quantity FROM stocks WHERE id=?');$q->execute([$id]);$cur=$q->fetchColumn();if($cur===false){flash('Item not found.','error');}elseif($act==='remove'&&$amount>(int)$cur){flash('Not enough stock.','error');}else{$delta=$act==='add'?$amount:-$amount;db()->prepare('UPDATE stocks SET quantity=quantity+? WHERE id=?')->execute([$delta,$id]);flash('Stock quantity updated.');}}redirect('stocks.php');}$pageTitle='Stocks';$all=stocks();$recs=low_stocks();require 'partials/header.php'; ?><div class="stocks-page"><h1 class="stocks-title">All Stocks</h1><div class="stocks-grid"><div class="stocks-graph panel"><h2>Current Stock Levels</h2><div class="chartbox"><canvas id="stockChart"></canvas></div></div><div class="recommendations-panel panel"><h3 class="recommend-title">Restock Recommendations</h3><ul class="recommend-list"><?php if(!$recs):?><li class="recommend-empty">No restock needed</li><?php else:foreach($recs as $r):?><li class="recommend-item"><?=e($r['name'])?> - <?=e($r['totalQuantity'])?> <?=e($r['unit'])?></li><?php endforeach;endif;?></ul><a class="restock-btn btn" href="restock.php">➕ Restock</a></div></div><div class="stocks-table-section panel"><div class="table-wrap"><table class="stocks-table"><thead><tr><th>S.No.</th><th>Name</th><th>Quantity</th><th>Unit</th><th>Expiry</th><th>Actions</th></tr></thead><tbody><?php foreach($all as $i=>$s):?><tr><td><?=$i+1?></td><td><?=e($s['name'])?></td><td class="<?=((int)$s['quantity']<10?'low':((int)$s['quantity']<25?'medium':'high'))?>"><?=e($s['quantity'])?></td><td><?=e($s['unit'])?></td><td><?=e($s['expiry'])?></td><td><form method="post" class="actions"><input type="hidden" name="id" value="<?=$s['id']?>"><input type="number" min="1" name="amount" placeholder="Qty" style="width:90px"><button name="action" value="add">+</button><button name="action" value="remove">−</button><button name="action" value="delete" onclick="return confirm('Delete this item?')">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><script>new Chart(document.getElementById('stockChart'),{type:'bar',data:{labels:<?=json_encode(array_column($all,'name'))?>,datasets:[{label:'Quantity',data:<?=json_encode(array_map('intval',array_column($all,'quantity')))?>,backgroundColor:'#FF69B4'}]},options:{responsive:true}});</script><?php require 'partials/footer.php'; ?>